# Analyzing horizontal and vertical connections between 4s
input_grid = [
    [9, 9, 9, 9, 4, 9, 4, 4, 4, 9, 4, 4, 4, 9, 4, 4, 9, 9, 4],
    [9, 9, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 4],
    [9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 4, 9, 4, 4, 4, 4, 9, 9, 4, 4, 4, 4, 4, 4, 4],
    [9, 9, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 4, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 4],
    [9, 9, 9, 9, 4, 4, 9, 4, 9, 4, 4, 9, 9, 4, 9, 4, 9, 4, 4],
    [9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9],
    [9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9, 9]
]

# Get all (row, col) positions with 4
positions = [(r, c) for r in range(10) for c in range(19) if input_grid[r][c] == 4]

# Look for vertical lines (same column, adjacent rows)
vertical_lines = {}
for r, c in positions:
    if c not in vertical_lines:
        vertical_lines[c] = []
    vertical_lines[c].append(r)

print("Vertical line positions (col -> [row indices]):")
for c in sorted(vertical_lines.keys()):
    print(f"  Col {c}: {vertical_lines[c]}")

# Look for horizontal segments (same row, adjacent columns)
horizontal_segments = {}
for r in range(10):
    segments = []
    current_start = None
    for c in range(19):
        if input_grid[r][c] == 4:
            if current_start is None:
                current_start = c
        else:
            if current_start is not None:
                segments.append((current_start, c - 1))
                current_start = None
    if current_start is not None:
        segments.append((current_start, min(current_start + 4, 18)))  # At least 2 adjacent
    if segments:
        horizontal_segments[r] = segments

print("\nHorizontal segments (row -> [(start_col, end_col)]):")
for r in sorted(horizontal_segments.keys()):
    print(f"  Row {r}: {horizontal_segments[r]}")

